import React, { useEffect, useState } from 'react';
import api from './api.ts';
import { useAuth } from './context/AuthContext.tsx';
import { useNavigate } from 'react-router-dom';

interface User {
  id: number;
  nome: string;
  email: string;
  role: 'admin' | 'licenciado';
}

const AdminUsers: React.FC = () => {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [users, setUsers] = useState<User[]>([]);
  const [form, setForm] = useState({ nome: '', email: '', password: '', role: 'licenciado' });
  const [editingUser, setEditingUser] = useState<User | null>(null);

  useEffect(() => {
    if (!user) {
      navigate('/');
    } else if (user.role !== 'admin') {
      alert('Acesso restrito a administradores.');
      navigate('/dashboard');
    }
  }, [user, navigate]);

  const fetchUsers = async () => {
    const res = await api.get('/api/admin/users');
    setUsers(res.data);
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingUser) {
      await api.put(`/api/admin/users/${editingUser.id}`, {
        nome: editingUser.nome,
        role: editingUser.role
      });
      setEditingUser(null);
    } else {
      await api.post('/api/admin/users', form);
      setForm({ nome: '', email: '', password: '', role: 'licenciado' });
    }
    fetchUsers();
  };

  const handleDelete = async (id: number) => {
    if (window.confirm('Tem certeza que deseja excluir este usuário?')) {
      await api.delete(`/api/admin/users/${id}`);
      fetchUsers();
    }
  };

  const startEdit = (u: User) => {
    setEditingUser(u);
  };

  return (
    <div className="p-2">
      <h2>{editingUser ? 'Editar Usuário' : 'Criar Usuário'}</h2>
      <form onSubmit={handleSubmit}>
        <input
          placeholder="Nome"
          value={editingUser ? editingUser.nome : form.nome}
          onChange={e => {
            if (editingUser) setEditingUser({ ...editingUser, nome: e.target.value });
            else setForm({ ...form, nome: e.target.value });
          }}
          required
        />
        {!editingUser && (
          <>
            <input
              placeholder="Email"
              type="email"
              value={form.email}
              onChange={e => setForm({ ...form, email: e.target.value })}
              required
            />
            <input
              placeholder="Senha"
              type="password"
              value={form.password}
              onChange={e => setForm({ ...form, password: e.target.value })}
              required
            />
          </>
        )}
        <select
          value={editingUser ? editingUser.role : form.role}
          onChange={e => {
            if (editingUser) setEditingUser({ ...editingUser, role: e.target.value as 'admin' | 'licenciado' });
            else setForm({ ...form, role: e.target.value as 'admin' | 'licenciado' });
          }}
        >
          <option value="licenciado">Licenciado</option>
          <option value="admin">Admin</option>
        </select>
        <button type="submit">{editingUser ? 'Salvar Alterações' : 'Criar Usuário'}</button>
        {editingUser && (
          <button type="button" onClick={() => setEditingUser(null)}>
            Cancelar Edição
          </button>
        )}
      </form>

      <h3>Usuários Cadastrados:</h3>
      <ul>
        {users.map(u => (
          <li key={u.id}>
            <strong>{u.nome}</strong> - {u.email} -({u.role})
            <button onClick={() => startEdit(u)}>Editar</button>
            <button onClick={() => handleDelete(u.id)}>Excluir</button>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default AdminUsers;
